from __future__ import annotations

from dataclasses import dataclass


VALID_ACTION_TYPES = {"downsize_cpu", "downsize_memory", "upsize_cpu", "no_op"}
DOWNSIZING_TYPES = frozenset({"downsize_cpu", "downsize_memory"})


@dataclass(frozen=True)
class WorkloadMetrics:
    service_name: str
    cpu_utilization_percent: int
    memory_utilization_percent: int
    p95_latency_ms: int
    error_rate_percent: float

    def __post_init__(self) -> None:
        if not self.service_name.strip():
            raise ValueError("service_name required")
        if not 0 <= self.cpu_utilization_percent <= 100:
            raise ValueError("cpu_utilization_percent must be between 0 and 100")
        if not 0 <= self.memory_utilization_percent <= 100:
            raise ValueError("memory_utilization_percent must be between 0 and 100")
        if self.p95_latency_ms < 0:
            raise ValueError("p95_latency_ms must be non-negative")
        if self.error_rate_percent < 0:
            raise ValueError("error_rate_percent must be non-negative")

    def utilization_vector(self) -> tuple[int, int]:
        return (self.cpu_utilization_percent, self.memory_utilization_percent)


@dataclass(frozen=True)
class SloState:
    service_name: str
    latency_target_ms: int
    error_budget_burn_rate: float
    active_incident: bool = False

    def __post_init__(self) -> None:
        if not self.service_name.strip():
            raise ValueError("service_name required")
        if self.latency_target_ms <= 0:
            raise ValueError("latency_target_ms must be positive")
        if self.error_budget_burn_rate < 0:
            raise ValueError("error_budget_burn_rate must be non-negative")

    def slo_subject(self) -> str:
        return self.service_name.strip()


@dataclass(frozen=True)
class OptimizationAction:
    action_id: str
    service_name: str
    action_type: str
    projected_monthly_savings_cents: int
    resource_delta_percent: int

    def __post_init__(self) -> None:
        if not self.action_id.strip():
            raise ValueError("action_id required")
        if not self.service_name.strip():
            raise ValueError("service_name required")
        if self.action_type not in VALID_ACTION_TYPES:
            raise ValueError("unsupported action_type")
        if self.projected_monthly_savings_cents < 0:
            raise ValueError("projected_monthly_savings_cents must be non-negative")
        if not -100 <= self.resource_delta_percent <= 100:
            raise ValueError("resource_delta_percent must be between -100 and 100")


def is_downsize_action(action_type: str) -> bool:
    return action_type in DOWNSIZING_TYPES


def format_action_label(action: OptimizationAction) -> str:
    return f"{action.action_id}:{action.action_type}"


def telemetry_bundle_key(metrics: WorkloadMetrics, slo: SloState) -> str:
    return f"{metrics.service_name}||{slo.service_name}"


def is_same_service_metrics(metrics: WorkloadMetrics, slo: SloState) -> bool:
    return metrics.service_name == slo.service_name

