from __future__ import annotations

"""Evaluate Turbonomic-style actions against Instana workload + SLO telemetry."""

from optimization_models import OptimizationAction, SloState, WorkloadMetrics
from slo_signals import UTILIZATION_HEADROOM_CEILING_PERCENT

DOWNSIZE_ACTIONS = {"downsize_cpu", "downsize_memory"}


def _decision(action: OptimizationAction, approved: bool, reason: str) -> dict[str, object]:
    return {
        "action_id": action.action_id,
        "service_name": action.service_name,
        "action_type": action.action_type,
        "approved": approved,
        "reason": reason,
        "projected_monthly_savings_cents": action.projected_monthly_savings_cents,
        "resource_delta_percent": action.resource_delta_percent,
    }


def _metrics_by_service(metrics: list[WorkloadMetrics]) -> dict[str, WorkloadMetrics]:
    return {item.service_name: item for item in metrics}


def _slos_by_service(slos: list[SloState]) -> dict[str, SloState]:
    return {item.service_name: item for item in slos}


def _has_utilization_headroom(metrics: WorkloadMetrics, action: OptimizationAction) -> bool:
    if action.action_type == "downsize_cpu":
        return metrics.cpu_utilization_percent < UTILIZATION_HEADROOM_CEILING_PERCENT
    if action.action_type == "downsize_memory":
        return metrics.memory_utilization_percent < UTILIZATION_HEADROOM_CEILING_PERCENT
    return True


def evaluate_rightsizing_actions(
    metrics: list[WorkloadMetrics],
    slos: list[SloState],
    actions: list[OptimizationAction],
) -> dict[str, object]:
    metrics_index = _metrics_by_service(metrics)
    slos_index = _slos_by_service(slos)
    decisions: list[dict[str, object]] = []

    for action in actions:
        service_metrics = metrics_index.get(action.service_name)
        service_slo = slos_index.get(action.service_name)
        if service_metrics is None or service_slo is None:
            decisions.append(_decision(action, False, "missing_telemetry"))
            continue

        if action.action_type in DOWNSIZE_ACTIONS and not _has_utilization_headroom(service_metrics, action):
            decisions.append(_decision(action, False, "insufficient_resource_headroom"))
            continue

        decisions.append(_decision(action, True, "approved"))

    return summarize_recommendations(decisions)


def summarize_recommendations(decisions: list[dict[str, object]]) -> dict[str, object]:
    approved = [decision for decision in decisions if decision["approved"]]
    blocked = [decision for decision in decisions if not decision["approved"]]
    return {
        "approved_count": len(approved),
        "blocked_count": len(blocked),
        "approved_savings_cents": sum(int(decision["projected_monthly_savings_cents"]) for decision in approved),
        "blocked_savings_cents": sum(int(decision["projected_monthly_savings_cents"]) for decision in blocked),
        "approved_actions": approved,
        "blocked_actions": blocked,
        "decisions": decisions,
    }


class InstanaTurbonomicGate:
    """Binds frozen metrics + SLO rows to iterative optimization action batches."""

    def __init__(self, metrics: list[WorkloadMetrics], slos: list[SloState]) -> None:
        self.metrics = list(metrics)
        self.slos = list(slos)

    def evaluate(self, actions: list[OptimizationAction]) -> dict[str, object]:
        return evaluate_rightsizing_actions(self.metrics, self.slos, actions)

