from __future__ import annotations

"""Instana-style SLO and saturation helpers for Turbonomic rightsizing gates."""

from optimization_models import SloState, WorkloadMetrics, VALID_ACTION_TYPES

ERROR_BUDGET_BURN_CRITICAL_RATE = 1.0
LATENCY_HEADROOM_RATIO_WARN = 0.85
UTILIZATION_HEADROOM_CEILING_PERCENT = 50


def latency_slo_violated(metrics: WorkloadMetrics, slo: SloState) -> bool:
    return metrics.p95_latency_ms > slo.latency_target_ms


def error_budget_is_burning(slo: SloState, critical_rate: float = ERROR_BUDGET_BURN_CRITICAL_RATE) -> bool:
    if critical_rate < 0:
        raise ValueError("critical_rate must be non-negative")
    return slo.error_budget_burn_rate > critical_rate


def incident_active(slo: SloState) -> bool:
    return slo.active_incident


def reliability_blocks_downsize(slo: SloState, metrics: WorkloadMetrics) -> tuple[bool, str]:
    if incident_active(slo):
        return True, "active_incident"
    if latency_slo_violated(metrics, slo):
        return True, "latency_slo_violated"
    if error_budget_is_burning(slo):
        return True, "error_budget_burn"
    return False, "approved"


def latency_margin_ms(metrics: WorkloadMetrics, slo: SloState) -> int:
    return slo.latency_target_ms - metrics.p95_latency_ms


def approaching_latency_target(metrics: WorkloadMetrics, slo: SloState) -> bool:
    if slo.latency_target_ms <= 0:
        return False
    ratio = metrics.p95_latency_ms / slo.latency_target_ms
    return ratio >= LATENCY_HEADROOM_RATIO_WARN


def service_telemetry_key(service_name: str) -> str:
    return f"svc::{service_name.strip()}"


def is_resource_downsize(action_type: str) -> bool:
    return action_type in {"downsize_cpu", "downsize_memory"}


def is_resource_upsize(action_type: str) -> bool:
    return action_type in {"upsize_cpu"}


def describe_slo_burn_state(burn_rate: float) -> str:
    if burn_rate <= 0:
        return "no_burn"
    if burn_rate <= ERROR_BUDGET_BURN_CRITICAL_RATE:
        return "within_budget"
    return "burning"


def action_affects_capacity(action_type: str) -> bool:
    return action_type in VALID_ACTION_TYPES and action_type != "no_op"


def merge_decision_reasons(*reasons: str) -> str:
    return ";".join(part for part in reasons if part)


def savings_weighted_priority(savings_cents: int, blocks_slo: bool) -> float:
    if blocks_slo:
        return float(savings_cents) * 0.25
    return float(savings_cents)


def burn_rate_severity_label(rate: float) -> str:
    if rate <= 0.25:
        return "low"
    if rate <= ERROR_BUDGET_BURN_CRITICAL_RATE:
        return "moderate"
    return "severe"

